/**
 * The types `mechanics/labs/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LabResearchTable, LabMultInput
 * depends    —
 * used by    src/mechanics/labs/index, src/mechanics/labs/research
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from research.ts

export interface LabResearchTable {
  /** Per-lab base benefit at level 0 (or flat base). */
  baseBenefit: readonly number[]
  /** Per-lab per-level increase when curve uses multiply mode. */
  benefitIncrease?: readonly number[]
  /** When true, mult = base × increase; when false, mult = base only. */
  usesIncreaseCurve?: readonly boolean[]
}

export interface LabMultInput {
  labIndex: number
  /** Current selected lab level (0 if locked). */
  labLevel: number
  tables: LabResearchTable
}
